const b=$('A1 webhook omni-in').item.json.body||{};
const esc=r.sentiment<=-0.3||r.intent==='complaint';
return [{ json: { Time:new Date().toISOString(), Channel:b.channel||'web', From:b.from||b.name||'', Message:b.message||'', Intent:r.intent, Sentiment:r.sentiment, Reply:r.reply, Escalated:esc?'yes':'no', esc } }];

const GOLD=5000,PLAT=15000,REF=500;const b=$('C1 webhook sale-in').item.json.body||{};
const ph=String(b.phone||'').replace(/\D/g,'').slice(-10); if(!ph) return [];
const tier=p=>p>=PLAT?'Platinum':p>=GOLD?'Gold':'Silver';
const rows=items.map(i=>i.json);const me=rows.find(r=>String(r.Phone||'').replace(/\D/g,'').slice(-10)===ph);
const add=Math.floor(Number(b.amount||0)/100);const np=Number(me?.Points||0)+add;
const out=[{json:{k:'cust',Phone:ph,Name:b.name||me?.Name||'Customer',Points:np,Tier:tier(np),TotalSpend:Number(me?.TotalSpend||0)+Number(b.amount||0),up:me&&tier(np)!==tier(Number(me.Points||0)),add}}];
const rp=String(b.referred_by||'').replace(/\D/g,'').slice(-10);
if(rp){const ref=rows.find(r=>String(r.Phone||'').replace(/\D/g,'').slice(-10)===rp);if(ref)out.push({json:{k:'ref',Phone:rp,Name:ref.Name,Points:Number(ref.Points||0)+REF,Tier:tier(Number(ref.Points||0)+REF),TotalSpend:Number(ref.TotalSpend||0),up:false,add:REF}})}
