const t=new Date().toISOString().slice(0,10);const td=new Date(t);
const enq=$('D2 read enquiries').all().map(i=>i.json);
const bri=$('D3 read bridal').all().map(i=>i.json);
const cus=$('D4 read customers').all().map(i=>i.json);
const fu =$('D5 read followups').all().map(i=>i.json);
const wa=(p,m)=>`https://wa.me/${String(p).replace(/\D/g,'')}?text=${encodeURIComponent(m)}`;
let out=[];
// 1 follow-ups due
const due=enq.filter(r=>r.FollowUp&&r.FollowUp<=t&&!['Sold','Lost'].includes(r.Status));
if(due.length)out.push('⏰ FOLLOW-UPS ('+due.length+'):\n'+due.slice(0,10).map(r=>'• '+r.Customer+' ('+(r.Item||'')+') '+(r.Phone?wa(r.Phone,'Namaste '+r.Customer+' ji! Just checking in about '+(r.Item||'your enquiry')+' 💛'):'')).join('\n'));
// 2 bridal drip
const MAP={180:'inspiration',90:'trousseau checklist + private preview',60:'reserve pieces — karigar lead time',30:'final fitting + rate-lock',7:'we are ready for your big week',(-15):'congratulations + review + anniversary noted'};
const touches=bri.filter(r=>r.WeddingDate&&r.Phone&&r.LastTouch!==t).map(r=>({r,d:Math.round((new Date(r.WeddingDate)-td)/864e5)})).filter(x=>MAP[x.d]);
if(touches.length)out.push('💍 BRIDAL TOUCHES:\n'+touches.map(x=>'• '+x.r.Name+' (T'+(x.d>=0?'-':'+')+Math.abs(x.d)+'): '+MAP[x.d]+' → '+wa(x.r.Phone,'Namaste '+x.r.Name+' ji! '+MAP[x.d]+' — shall we plan it together? ✨ '+($env.BRAND_NAME||''))).join('\n'));
// 3 occasions in 7 days
const md=(dt)=>dt.slice(5,10);const in7=new Date(Date.now()+7*864e5).toISOString();
const occ=cus.filter(r=>r.OccasionDate&&r.Phone&&md(r.OccasionDate.padStart(10,'0'))===md(in7));
if(occ.length)out.push('🎁 OCCASIONS in 7d:\n'+occ.map(r=>'• '+r.Name+' ('+(r.Occasion||'occasion')+') → '+wa(r.Phone,'Namaste '+r.Name+' ji! A special day is coming 💛 Make it golden — reply and we will keep a selection ready.')).join('\n'));
// 4 review asks due
const rev=fu.filter(r=>r.Kind==='review'&&r.Done!=='yes'&&r.Due<=t);
if(rev.length)out.push('⭐ REVIEW ASKS:\n'+rev.map(r=>'• '+r.Name+' → '+wa(r.Phone,'Namaste '+r.Name+' ji! Hope you are loving your jewellery 💛 A small Google review would bless our family business: '+($env.REVIEW_LINK||''))).join('\n'));
return [{ json: { text: out.length?out.join('\n\n'):'✅ Lifecycle engine: nothing due today.' } }];
